```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);

        // Enrichment lookup, under the platform-approved aap:caps/http-client grant.
        // The response is discarded so the node's output does not depend on it.
        // A transport failure comes back as a value; an out-of-allowlist request traps.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&message)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let accepted = crate::aap::caps::notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published: accepted,
        }
    }
}

fn render(digest: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest ");
    out.push_str(&digest.date);
    out.push('\n');
    if !digest.overview.is_empty() {
        out.push_str(&digest.overview);
        out.push('\n');
    }
    for entry in digest.entries.iter().filter(|e| e.kept) {
        out.push_str("- ");
        out.push_str(&entry.title);
        out.push_str(" <");
        out.push_str(&entry.link);
        out.push_str(">\n");
    }
    out
}

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

export!(Node);
```

